-- Target database: acore_world
--
-- AzerothQuest quest pack: map areas for quests 900001-900086.
-- The world map's objective areas and turn-in markers (quest_poi, quest_poi_points), built by
-- tools/questpack/build_quest_poi.py from the creatures' spawns: one area per spawn group, the convex hull
-- of its spawns; ObjectiveIndex 0-1 kill objectives, 4 the quest item, -1 the turn-in.
--
-- Safe to run twice. Restart the worldserver afterwards.

DELETE FROM `quest_poi` WHERE `QuestID` BETWEEN 900001 AND 900086;

DELETE FROM `quest_poi_points` WHERE `QuestID` BETWEEN 900001 AND 900086;

